def flat = [:];
for (def forecast : ctx.forecasts) {
  def key = forecast.date + ' ' + forecast.time;
  def snow = 0.0f;
  def freezing = null;
  def humidity = null;
  try { if (forecast.snow != null) { snow = Float.parseFloat(forecast.snow.replace('cm', '').trim()); } } catch (NumberFormatException e) {}
  try { if (forecast.freezing_level != null) { freezing = Integer.parseInt(forecast.freezing_level.trim()); } } catch (NumberFormatException e) {}
  try { if (forecast.humidity != null) { humidity = Integer.parseInt(forecast.humidity.trim()); } } catch (NumberFormatException e) {}
  flat[key] = [
    'snow': snow,
    'freezing_level': freezing,
    'humidity': humidity,
    'wind': forecast.wind
  ];
}
ctx.forecasts_flat = flat;
